<h1 class="h3 mb-3">Record Sale</h1><div class="card shadow-sm"><div class="card-body p-4"><?php if(!$products): ?><div class="alert alert-warning">There are no products with available stock. Add or restock a product first.</div><?php endif ?><?= form_open('sales/create') ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Product *</label><select class="form-select" name="product_id" id="product" required><option value="">Select a product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" data-price="<?= $p['price'] ?>" <?= old('product_id')==$p['id']?'selected':'' ?>><?= esc($p['name']) ?> — ₱<?= number_format($p['price'],2) ?> (<?= $p['stock_quantity'] ?> in stock)</option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Customer (optional)</label><select class="form-select" name="customer_id"><option value="">Walk-in Customer</option><?php foreach($customers as $c): ?><option value="<?= $c['id'] ?>" <?= old('customer_id')==$c['id']?'selected':'' ?>><?= esc($c['full_name']) ?></option><?php endforeach ?></select></div><div class="col-md-4"><label class="form-label">Quantity *</label><input class="form-control" id="quantity" type="number" min="1" name="quantity" value="<?= old('quantity',1) ?>" required></div><div class="col-md-4"><label class="form-label">Estimated Total</label><div class="form-control bg-light fw-bold" id="total">₱0.00</div></div></div><div class="mt-4"><button class="btn btn-primary" <?= !$products?'disabled':'' ?>>Complete Sale</button><a class="btn btn-light" href="<?= site_url('sales') ?>">Cancel</a></div><?= form_close() ?></div></div><script>const p=document.querySelector('#product'),q=document.querySelector('#quantity'),t=document.querySelector('#total');function total(){const o=p.options[p.selectedIndex],price=Number(o?.dataset.price||0),qty=Number(q.value||0);t.textContent='₱'+(price*qty).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}p.addEventListener('change',total);q.addEventListener('input',total);total();</script>
